const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Alisal Fire location (Santa Barbara County, California)
  const fireRegion = ee.Geometry.Rectangle([-120.3, 34.4, -119.9, 34.7]);

  // Date ranges
  const preFireStart = '2021-10-01';
  const preFireEnd = '2021-10-10';
  const fireStart = '2021-10-11';
  const fireEnd = '2021-10-13';

  // Cloud masking function for Sentinel-2
  function maskClouds(image) {
    const scl = image.select('SCL');
    const mask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10));
    return image.updateMask(mask);
  }

  // NBR calculation
  function addNBR(image) {
    const nbr = image.normalizedDifference(['B8', 'B12']).rename('NBR');
    return image.addBands(nbr);
  }

  // Get pre-fire imagery
  let preFireCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(fireRegion)
    .filterDate(preFireStart, preFireEnd)
    .map(maskClouds)
    .map(addNBR);

  console.log('Pre-fire images:', preFireCol.size().getInfo());

  if (preFireCol.size().getInfo() === 0) {
    console.log('No pre-fire Sentinel-2 data, trying Landsat 8...');
    preFireCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(fireRegion)
      .filterDate(preFireStart, preFireEnd)
      .map(function(img) {
        const nbr = img.normalizedDifference(['SR_B5', 'SR_B7']).rename('NBR');
        return img.addBands(nbr);
      });
    console.log('Pre-fire Landsat images:', preFireCol.size().getInfo());
  }

  if (preFireCol.size().getInfo() === 0) {
    console.log('No pre-fire data available.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get during/post-fire imagery
  let postFireCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(fireRegion)
    .filterDate(fireStart, fireEnd)
    .map(maskClouds)
    .map(addNBR);

  console.log('Post-fire images:', postFireCol.size().getInfo());

  if (postFireCol.size().getInfo() === 0) {
    console.log('No post-fire data, extending date range to Oct 14-20...');
    postFireCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(fireRegion)
      .filterDate(fireStart, '2021-10-20')
      .map(maskClouds)
      .map(addNBR);
    console.log('Extended post-fire images:', postFireCol.size().getInfo());
  }

  if (postFireCol.size().getInfo() === 0) {
    console.log('No post-fire data available.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Create composite images
  const preFire = preFireCol.select('NBR').median();
  const postFire = postFireCol.select('NBR').median();

  // Calculate dNBR (difference NBR)
  const dNBR = preFire.subtract(postFire).rename('dNBR');

  // Threshold for burned areas (dNBR > 0.1 typically indicates burn)
  const burnedArea = dNBR.gt(0.1);

  // Count valid pixels
  const pixelCount = burnedArea.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: fireRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('dNBR').getInfo();

  console.log('Valid pixels:', pixelCount);

  if (pixelCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate burned area in square meters
  const areaSqMeters = burnedArea.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: fireRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('dNBR').getInfo();

  if (areaSqMeters === null || areaSqMeters === undefined) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert to acres (1 acre = 4046.86 square meters)
  const areaAcres = areaSqMeters / 4046.86;

  console.log('Burned area: ' + areaAcres.toFixed(0) + ' acres');
  console.log('Threshold: 10,000 acres');

  if (areaAcres < 10000) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
